/**
 * Resolves UI file paths for projects using legacy or fallback structure patterns.
 *
 * This function handles three distinct project structure scenarios:
 * 1. **New structure**: `<sourceRoot>/ui/main.tsx` exists - Returns new-structure paths
 * 2. **Legacy structure**: `<sourceRoot>/main.tsx` exists - Returns legacy-specific paths
 * 3. **No UI**: Neither `<sourceRoot>/ui/main.tsx` nor `<sourceRoot>/main.tsx` exist - Returns `null`
 *
 * @param root - Absolute path to the project root directory
 * @param sourceRoot - Relative path from root to source directory (e.g., 'src', './')
 * @param uiOptions - UI build source configuration from app.config options assets
 *
 * @returns {UiFilePaths | null} Resolved UI file paths, or `null` when no UI entry point exists.
 * Callers are responsible for deciding whether a missing UI is valid (e.g. hidden apps).
 *
 */
export declare function resolveUiFilePaths(root: string, sourceRoot: string, uiOptions: FrozenResolvedCliUiSource): UiFilePaths | null;
