/**
 * Merges `b` onto `a` and returns a new object. Neither input is mutated.
 *
 * Merge rules:
 * - **Plain objects** are deep-merged recursively (lodash `mergeWith` default behavior).
 * - **Arrays** are replaced wholesale — the array from `b` wins in its entirety.
 *   This differs from lodash's default, which would merge arrays index-by-index.
 * - **Arrays of objects for known keys** (`assets`, `actions`) additionally have
 *   per-item defaults from `arrayObjectDefaults` merged into every element before
 *   the array is set. This ensures, for example, that every asset always carries
 *   an `ignore` field even when the caller omitted it.
 * - **`undefined` values in `b`** are ignored; the corresponding value from `a`
 *   is kept. This lets partial configs omit fields without clearing them.
 */
export declare function mergeRecursively(a: any, b: any): any;
